from flask import Flask, redirect, request, abort
import re
from urllib.parse import urlparse

app = Flask(__name__)

allowed_domains = ['example.com', 'anotherexample.com']  # Allowed domains for redirection

@app.route('/redirect')
def redirectToTarget():
    target_url = request.args.get('url')

    if not target_url:
        return abort(400, description="Missing URL parameter.")

    parsed_url = urlparse(target_url)

    if not re.match(r'^https?://', target_url):
        return abort(400, description="Invalid URL scheme.")

    if parsed_url.netloc not in allowed_domains:
        return abort(400, description="URL is not allowed.")

    app.logger.info(f'Redirecting to: {target_url}')

    return redirect(target_url)

