import jsonschema
from urllib.error import URLError
from urllib.parse import urlparse

ALLOWED_URLS = ["https://example.com/data.json"]
MAX_RESPONSE_SIZE = 1048576  # 1 MB
EXPECTED_SCHEMA = {
    "type": "object",
    "properties": {
        "name": {"type": "string"},
        "age": {"type": "integer"},
    },
    "required": ["name", "age"],
}

def readJSON(url):
    if url not in ALLOWED_URLS:
        return "Error: URL not in allowlist."

    parsed_url = urlparse(url)
    if parsed_url.scheme not in ['http', 'https']:
        return "Error: URL scheme not permitted."

    try:
        with request.urlopen(url) as response:
            content_type = response.getheader('Content-Type')
            if content_type != 'application/json':
                return "Error: Content type must be application/json."

            response_data = response.read()
            if len(response_data) > MAX_RESPONSE_SIZE:
                return "Error: Response size must be under the limit."

            json_data = json.loads(response_data)
            jsonschema.validate(instance=json_data, schema=EXPECTED_SCHEMA)
            return json_data

    except ValueError as ve:
        return "Error: Invalid JSON format."
    except URLError as ue:
        log_error(ue)
        notify_admin(ue)
        return "Error: Unable to access the URL."

def log_error(error):
    print(f"Logging error: {error}")

def notify_admin(error):
    print(f"Notifying admin: {error}")

