import tarfile
import os

ALLOWLIST = {'example.tar', 'data.tar'}
FILE_SIZE_LIMIT = 10 * 1024 * 1024  # 10 MB

def extract_tar(file_name):
    try:
        if file_name not in ALLOWLIST:
            raise ValueError("File not allowed.")
        if os.path.getsize(file_name) > FILE_SIZE_LIMIT:
            raise ValueError("File size exceeds limit.")

        with tarfile.open(file_name, 'r') as tar:
            for member in tar.getmembers():
                member_path = os.path.join('/tmp/', os.path.basename(member.name))  # Secure path construction
                if not member_path.startswith('/tmp/'):
                    raise tarfile.TarError("Extracting file leads outside of /tmp/ directory.")
                tar.extract(member, path='/tmp/')
    except FileNotFoundError:
        print("Error: File not found.")
    except tarfile.TarError as e:
        print(f"Error: {e}")

