from flask import request, Flask, jsonify
import ldap3
import logging

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

@app.route("/normal")
def normal():
    try:
        dc = request.args.get('dc')
        username = request.args.get('username')

        if not dc or not username:
            return jsonify({"error": "Missing parameters."}), 400

        if not ldap3.utils.validations.validate_user(username):
            return jsonify({"error": "Malformed username."}), 400

        escaped_username = ldap3.utils.conv.escape_filter_chars(username)
        query = f"(&(objectClass=user)(sAMAccountName={escaped_username}))"

        connection = ldap3.Connection('ldap://localhost', auto_bind=True)
        connection.search(f"dc={dc},dc=com", query)

        if not connection.entries:
            return jsonify({"error": "User not found."}), 404

        logging.info(f"LDAP Query: {query}")
        return jsonify({"user": connection.entries[0].entry_to_json}), 200

    except ldap3.ConnectionError:
        return jsonify({"error": "Internal Server Error"}), 500
    except ValueError:
        return jsonify({"error": "Bad Request"}), 400
    except ldap3.LDAPSearchError:
        return jsonify({"error": "Not Found"}), 404

if __name__ == "__main__":
    app.run(debug=False)

