from flask import request, send_file, Flask, abort
import os

app = Flask(__name__)
allowed_extensions = {'.txt', '.pdf', '.jpg'}
allowed_paths = ['/safe/files/']

def secure_filename(filename):
    return os.path.basename(filename)

def is_file_allowed(filename):
    return any(filename.endswith(ext) for ext in allowed_extensions)

def is_path_allowed(path):
    return any(os.path.abspath(path).startswith(os.path.abspath(allowed_path)) for allowed_path in allowed_paths)

@app.route('/download')
def download():
    filename = request.args.get('file')
    if not filename:
        abort(404)

    sanitized_filename = secure_filename(filename)
    file_path = os.path.join('/base/directory', sanitized_filename)

    if not is_path_allowed(file_path):
        app.logger.warning(f'Unauthorized access attempt to {file_path}.')
        abort(403)

    try:
        if not os.path.isfile(file_path):
            abort(404)
        return send_file(file_path)
    except FileNotFoundError:
        abort(404)
    except SecurityError:
        return abort(403)

