ALLOWED_DOMAINS = ["https://semmle.com"]
MAX_RETRIES = 3
TIMEOUT = 5  # Added timeout for requests

def make_request(url):
    if url not in ALLOWED_DOMAINS:
        return "This domain is not allowed."

    retries = 0
    while retries < MAX_RETRIES:
        try:
            response = requests.get(url, timeout=TIMEOUT)  # Added timeout parameter
            response.raise_for_status()
            if response.status_code == 200:
                return response.text
        except HTTPError as http_err:
            log_error(http_err)
            return "An error occurred while processing your request. Please try again later."
        except ConnectionError:
            retries += 1
            if retries == MAX_RETRIES:
                return "Failed to connect after several attempts. Please check your connection."
        except Timeout:
            log_timeout_error()
            return "Request timed out. Please try again."

    return "An unexpected error occurred."

