from socket import socket, bind, listen, accept, recv, send, error as SocketError
import logging

MAX_PAYLOAD_SIZE = 1024
ALLOWED_IPS = {'127.0.0.1'}
ALLOWED_PORTS = {8080}

def log_error(message):
    logging.error(message)

def echoServer(port):
    if port not in ALLOWED_PORTS:
        raise ValueError("Port not allowed.")

    server_socket = socket()
    bind(server_socket, ('', port))
    listen(server_socket)

    while True:
        try:
            client_socket, addr = accept(server_socket)
            if addr[0] not in ALLOWED_IPS:
                log_error("Connection attempt from unauthorized IP: {}".format(addr[0]))
                client_socket.close()
                continue

            data = recv(client_socket, MAX_PAYLOAD_SIZE)
            if len(data) > MAX_PAYLOAD_SIZE:
                log_error("Received data exceeds maximum payload size.")
                client_socket.close()
                continue

            send(client_socket, data)

        except SocketError as e:
            log_error("Socket error occurred: {}".format(e))
            client_socket.close()

