def xpath_query(request):
    try:
        xml_input = request.GET.get('xml')
        xpath_input = request.GET.get('xpath')

        if xml_input is None or xpath_input is None:
            return HttpResponse("400 Bad Request", status=400)

        schema = etree.XMLSchema(etree.XML("<schema><element name='tag'/></schema>"))
        xmlparser = etree.XMLParser(schema=schema)

        xml_doc = etree.parse(StringIO(xml_input), xmlparser)

        result = etree.XPath(f"/tag[@id='{xpath_input}']")(xml_doc)

        return HttpResponse(str(result))

